"use strict";
(() => {
const $=s=>document.querySelector(s),dialog=$('#loginDialog'),form=$('#publicLoginForm'),error=$('#loginError'),button=$('#submitLogin');
let lang;try{lang=localStorage.getItem('ac-language');}catch(_){}lang=lang==='en'?'en':'ru';
const ru=Object.fromEntries([...document.querySelectorAll('[data-i18n]')].map(el=>[el.dataset.i18n,el.textContent]));
const en={nav:'How it works',signIn:'Sign in ↗',eyebrow:'NOTES ON THE DIGITAL WORLD',titleOne:'The internet,',titleTwo:'a little closer.',intro:'Behind every website is a small journey of data. Discover how addresses, networks and servers connect us to one another.',explore:'Follow the journey',caption:'From a single click to the whole world',visualLabel:'THE ANATOMY OF A REQUEST',device:'Your device',network:'Network',server:'Server',visualBottom:'Millions of routes. One network.',basicsTitle:'One big network. Three simple ideas.',reading:'READING · 2 MINUTES',dnsTitle:'Everything has an address',dnsText:'A domain is a human-readable website name. DNS helps find its corresponding IP address so your device knows where to send a request.',routeTitle:'Data follows routes',routeText:'Information is divided into packets. Routers pass them between networks, choosing the next step towards their destination.',webTitle:'A website is a conversation',webText:'Your browser requests a page and a server responds. HTTPS encrypts the exchange and lets your browser verify the server’s identity.',footer:'Complex things, simply explained.',toTop:'Back to top ↑',loginTitle:'Welcome back',loginIntro:'Sign in to your account to continue.',username:'Username',password:'Password',continue:'Sign in to your account'};
function translate(){document.documentElement.lang=lang;document.title=lang==='en'?'Atlas — understanding the internet':'Atlas — как устроен интернет';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=(lang==='en'?en:ru)[el.dataset.i18n]);$('#languageToggle').textContent=lang==='ru'?'EN':'RU';$('#closeLogin').ariaLabel=lang==='ru'?'Закрыть':'Close';$('.network-visual').ariaLabel=lang==='ru'?'Путь данных: устройство, сеть, сервер':'Data journey: device, network, server';$('.site-header nav').ariaLabel=lang==='ru'?'Навигация':'Navigation';}
$('#languageToggle').onclick=()=>{lang=lang==='ru'?'en':'ru';try{localStorage.setItem('ac-language',lang);}catch(_){}error.textContent='';translate();};
$('#openLogin').onclick=()=>{error.textContent='';dialog.showModal();};$('#closeLogin').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{form.password.value='';error.textContent='';});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
async function json(url,options={}){const response=await fetch(url,{...options,credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok){const err=new Error();err.status=response.status;throw err;}return data;}
form.onsubmit=async event=>{event.preventDefault();if(button.disabled)return;button.disabled=true;error.textContent='';button.textContent=lang==='ru'?'Проверяем…':'Signing in…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const me=await json('/api/me',{signal:controller.signal});await json('/api/login',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','X-CSRF-Token':me.csrf},body:JSON.stringify({username:form.username.value,password:form.password.value})});form.password.value='';window.location.replace('/');}catch(err){error.textContent=err.status===401?(lang==='ru'?'Неверный логин или пароль.':'Invalid username or password.'):err.status===429?(lang==='ru'?'Слишком много попыток. Повторите через 5 минут.':'Too many attempts. Try again in 5 minutes.'):(lang==='ru'?'Не удалось войти. Проверьте соединение и повторите.':'Unable to sign in. Check your connection and try again.');form.password.value='';form.password.focus();}finally{clearTimeout(timer);button.disabled=false;button.textContent=(lang==='en'?en:ru).continue;}};
translate();
})();
